// === Flatten all parsed points (no ip), include job_uuid from global.config ===
// Reads:  global.grossList.<controller>.<ip>.points
// Adds:   job_uuid to every row (from global.config.JOB_UUID)
// Writes: msg.payload = flat array, msg.count

const controller = msg.controller || "larmia_controller";
const doSort = (msg.sort !== false); // default true

const root = global.get("grossList", "persistent") || {};
const controllers = root[controller] || {};

const cfg = global.get("config", "persistent") || {};
const jobUUID = cfg?.JOB_UUID ?? null;

const out = [];

// Walk all IP buckets under the chosen controller
for (const ip of Object.keys(controllers)) {
  const bucket = controllers[ip] || {};
  const pointsObj = bucket.points || {};

  for (const pid of Object.keys(pointsObj)) {
    const point = pointsObj[pid];
    if (!point) continue;

    // Remove hasValue from point
    const { hasValue, ...rest } = point;

    // Shallow copy without ip/hasValue, but add job_uuid
    out.push({ ...rest, job_uuid: jobUUID });
  }
}

// Optional stable sort: Property → system → PID (numeric-aware)
if (doSort) {
  out.sort((a, b) => {
    const pa = (a.Property || ""), pb = (b.Property || "");
    if (pa !== pb) return pa.localeCompare(pb);
    const sa = (a.system || ""), sb = (b.system || "");
    if (sa !== sb) return sa.localeCompare(sb);
    const pidA = String(a.PID ?? ""), pidB = String(b.PID ?? "");
    const na = parseInt(pidA, 10), nb = parseInt(pidB, 10);
    if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
    return pidA.localeCompare(pidB);
  });
}

msg.payload = out;
msg.count = out.length;
return msg;
